public class Carro {
    // atributos (características de cada carro)
    String cor;
    int velocidade;

    // método (comportamento de cada carro)
    void acelerar() {
        velocidade = velocidade + 10;
    }
}

public class Main {
    public static void main(String[] args) {
        // criando dois objetos (instâncias) a partir da classe Carro
        Carro carroDoJoao = new Carro();
        carroDoJoao.cor = "vermelho";
        carroDoJoao.acelerar();

        Carro carroDaMaria = new Carro();
        carroDaMaria.cor = "azul";

        System.out.println(carroDoJoao.velocidade); // 10
        System.out.println(carroDaMaria.velocidade); // 0
    }
}

public class Carro {
