public class Carro {
    private String cor;
    private int velocidade;

    public String getCor() {
        return cor;
    }

    public void setCor(String cor) {
        this.cor = cor;
    }

    public int getVelocidade() {
        return velocidade;
    }

    public void setVelocidade(int velocidade) {
        if (velocidade < 0) {
            throw new IllegalArgumentException("Velocidade não pode ser negativa");
        }
        this.velocidade = velocidade;
    }
}

public class Pessoa {
    private String nome;
    private int idade;

    public Pessoa(String nome, int idade) {
        // this.nome é o atributo; nome (sem this) é o parâmetro
        this.nome = nome;
        this.idade = idade;
    }

    public void aniversario() {
        this.idade = this.idade + 1;
        System.out.println(this.nome + " agora tem " + this.idade + " anos");
    }
}

public class Veiculo {
    protected int velocidade;

    public void acelerar() {
        velocidade += 10;
    }
}

// Carro herda tudo de Veiculo e ainda ganha algo próprio
public class Carro extends Veiculo {
    private int numeroDePortas = 4;

    public void buzinar() {
        System.out.println("Fon fon!");
    }
}

public class Main {
    public static void main(String[] args) {
        Carro carro = new Carro();
        carro.acelerar();   // método herdado de Veiculo
        carro.buzinar();    // método próprio de Carro
        System.out.println(carro.velocidade); // 10
    }
}

