public class Divisor {
    // 'throws' avisa que este método pode propagar essa exceção checked
    public static int lerEDividir(String texto, int divisor) throws NumberFormatException {
        int numero = Integer.parseInt(texto); // pode lançar NumberFormatException
        if (divisor == 0) {
            throw new ArithmeticException("Divisão por zero não é permitida");
        }
        return numero / divisor;
    }

    public static void main(String[] args) {
        try {
            int resultado = lerEDividir("10", 0);
            System.out.println(resultado);
        } catch (ArithmeticException e) {
            System.out.println("Erro matemático: " + e.getMessage());
        } catch (NumberFormatException e) {
            System.out.println("Texto inválido para número: " + e.getMessage());
        } finally {
            System.out.println("Isso sempre executa, com ou sem erro");
        }
    }
}

