import java.util.List;
import java.util.stream.Collectors;

public class Main {
    public static void main(String[] args) {
        List<String> nomes = List.of("Ana", "Bernardo", "Bruno", "Zé");

        List<String> nomesComB = nomes.stream()
                .filter(nome -> nome.startsWith("B"))   // mantém só os que começam com B
                .map(String::toUpperCase)                // transforma em maiúsculas
                .collect(Collectors.toList());            // reúne em uma nova lista

        System.out.println(nomesComB); // [BERNARDO, BRUNO]
    }
}

import java.io.BufferedReader;
import java.io.FileReader;
import java.io.IOException;

public class LeitorDeArquivo {
    public static void lerPrimeiraLinha(String caminho) {
        // o BufferedReader é fechado automaticamente ao final, mesmo se der erro
        try (BufferedReader leitor = new BufferedReader(new FileReader(caminho))) {
            String primeiraLinha = leitor.readLine();
            System.out.println(primeiraLinha);
        } catch (IOException e) {
            System.out.println("Erro ao ler o arquivo: " + e.getMessage());
        }
    }
}
